local GardenPotBrushMaker = {}
local PRODUCTS = {
    iron_gardenpotbrush = { name = "Železni ščetka za lonce", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni ščetka za lonce za vrtnarje." },
    bronze_gardenpotbrush = { name = "Bronast ščetka za lonce", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast ščetka za lonce za vrtnarje." },
    silver_gardenpotbrush = { name = "Srebrn ščetka za lonce", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn ščetka za lonce za vrtnarje." },
    gilded_gardenpotbrush = { name = "Pozlačen ščetka za lonce", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen ščetka za lonce za vrtnarje." },
    jewel_set_gardenpotbrush = { name = "Draguljast ščetka za lonce", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast ščetka za lonce za vrtnarje." },
    royal_sovereign_gardenpotbrush = { name = "Kraljevski suveren ščetka za lonce", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren ščetka za lonce z biseri za krono." },
}
