    gardenpotbrush_workshop = { name = "Gardenpotbrush delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    gardenpotbrush_house = { name = "Gardenpotbrush hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_gardenpotbrush_atelier = { name = "Mojstrski gardenpotbrush atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_gardenpotbrush_palace = { name = "Suverena gardenpotbrush palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
GardenPotBrushMaker.ironStock=10; GardenPotBrushMaker.bronzeStock=8; GardenPotBrushMaker.woodStock=14; GardenPotBrushMaker.leatherStock=14; GardenPotBrushMaker.silverStock=8; GardenPotBrushMaker.goldStock=6; GardenPotBrushMaker.jewelStock=4; GardenPotBrushMaker.pearlStock=4
GardenPotBrushMaker.productStock = {}; GardenPotBrushMaker.buildings = {}; GardenPotBrushMaker.maker = nil; GardenPotBrushMaker.activeMaking = {}; GardenPotBrushMaker.totalProducts = 0; GardenPotBrushMaker.dayTimer = 0
function GardenPotBrushMaker.init() GardenPotBrushMaker.ironStock=10; GardenPotBrushMaker.bronzeStock=8; GardenPotBrushMaker.woodStock=14; GardenPotBrushMaker.leatherStock=14; GardenPotBrushMaker.silverStock=8; GardenPotBrushMaker.goldStock=6; GardenPotBrushMaker.jewelStock=4; GardenPotBrushMaker.pearlStock=4; GardenPotBrushMaker.productStock={}; GardenPotBrushMaker.buildings={}; GardenPotBrushMaker.maker=nil; GardenPotBrushMaker.activeMaking={}; GardenPotBrushMaker.totalProducts=0; GardenPotBrushMaker.dayTimer=0; print("[GardenPotBrushMaker] Royal Garden Pot Brush Maker System initialized (6 products, 4 buildings)") end
function GardenPotBrushMaker.hireMaker(n,s) s=s or math.random(55,90); local c=575+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; GardenPotBrushMaker.maker={name=n or ("Ščetkar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščetkar najet: %s (spretnost: %d)",GardenPotBrushMaker.maker.name,s),"success") end; return true end
function GardenPotBrushMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function GardenPotBrushMaker.build(id) local ok,e=GardenPotBrushMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(GardenPotBrushMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function GardenPotBrushMaker.getQualityBonus() local b=0; for _,bd in ipairs(GardenPotBrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function GardenPotBrushMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and GardenPotBrushMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and GardenPotBrushMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and GardenPotBrushMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and GardenPotBrushMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and GardenPotBrushMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and GardenPotBrushMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and GardenPotBrushMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and GardenPotBrushMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #GardenPotBrushMaker.buildings==0 then return false,"Potrebna ščetna delavnica" end; if not GardenPotBrushMaker.maker then return false,"Potreben scetkar" end; return true end
function GardenPotBrushMaker.make(pt,qty) qty=qty or 1; local ok,e=GardenPotBrushMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then GardenPotBrushMaker.ironStock=GardenPotBrushMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then GardenPotBrushMaker.bronzeStock=GardenPotBrushMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then GardenPotBrushMaker.woodStock=GardenPotBrushMaker.woodStock-d.woodCost*qty end; if d.leatherCost then GardenPotBrushMaker.leatherStock=GardenPotBrushMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then GardenPotBrushMaker.silverStock=GardenPotBrushMaker.silverStock-d.silverCost*qty end; if d.goldCost then GardenPotBrushMaker.goldStock=GardenPotBrushMaker.goldStock-d.goldCost*qty end; if d.jewelCost then GardenPotBrushMaker.jewelStock=GardenPotBrushMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then GardenPotBrushMaker.pearlStock=GardenPotBrushMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if GardenPotBrushMaker.maker then t=math.max(1,t-math.floor(GardenPotBrushMaker.maker.skill/13)) end; table.insert(GardenPotBrushMaker.activeMaking,{id="gardenpotbrush_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function GardenPotBrushMaker.completeMaking(m) local q=1.0+(GardenPotBrushMaker.getQualityBonus()/100); if GardenPotBrushMaker.maker then q=q+(GardenPotBrushMaker.maker.skill/140) end; q=math.min(2.5,q); GardenPotBrushMaker.productStock[m.productType]=(GardenPotBrushMaker.productStock[m.productType] or 0)+m.quantity; GardenPotBrushMaker.totalProducts=GardenPotBrushMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if GardenPotBrushMaker.maker then GardenPotBrushMaker.maker.itemsMade=GardenPotBrushMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then GardenPotBrushMaker.maker.skill=math.min(100,GardenPotBrushMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Ščetka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"gardenpotbrush.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function GardenPotBrushMaker.update(dt) if not _G.state then return end; GardenPotBrushMaker.dayTimer=GardenPotBrushMaker.dayTimer+dt; if GardenPotBrushMaker.dayTimer>=30 then GardenPotBrushMaker.dayTimer=0; for i=#GardenPotBrushMaker.activeMaking,1,-1 do local m=GardenPotBrushMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then GardenPotBrushMaker.completeMaking(m); table.remove(GardenPotBrushMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(GardenPotBrushMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if GardenPotBrushMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function GardenPotBrushMaker.getStats() return {ironStock=GardenPotBrushMaker.ironStock,bronzeStock=GardenPotBrushMaker.bronzeStock,woodStock=GardenPotBrushMaker.woodStock,leatherStock=GardenPotBrushMaker.leatherStock,silverStock=GardenPotBrushMaker.silverStock,goldStock=GardenPotBrushMaker.goldStock,jewelStock=GardenPotBrushMaker.jewelStock,pearlStock=GardenPotBrushMaker.pearlStock,productStock=GardenPotBrushMaker.productStock,numBuildings=#GardenPotBrushMaker.buildings,hasMaker=GardenPotBrushMaker.maker~=nil,makerName=GardenPotBrushMaker.maker and GardenPotBrushMaker.maker.name or "—",makerSkill=GardenPotBrushMaker.maker and GardenPotBrushMaker.maker.skill or 0,activeMaking=#GardenPotBrushMaker.activeMaking,totalProducts=GardenPotBrushMaker.totalProducts} end
return GardenPotBrushMaker
